<body>
<div class="rel" id="relBar">
  <div class="rel-title" onclick="this.parentElement.classList.toggle('open')">
    <span>💛 人际关系</span><span class="arrow">▼</span>
  </div>
  <div class="rel-wrap">
    <div class="rel-body">
      <div class="npc-list" id="npcList"></div>
    </div>
  </div>
</div>

<script>
(function(){
  var raw = `$1`;
  var maxHearts = 10;
  var lines = raw.split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var container = document.getElementById("npcList");

  lines.forEach(function(line){
    var parts = line.split("|");
    var name = parts[0].trim();
    var map = {};
    for(var i=1;i<parts.length;i++){
      var kv = parts[i].split("=");
      if(kv.length===2) map[kv[0].trim()] = kv[1].trim();
    }
    var type = map["类型"]||"";
    var heartNum = parseInt(map["心数"])||0;
    var stage = map["阶段"]||"";

    var card = document.createElement("div");
    card.className = "npc-card";

    /* 顶行 */
    var top = document.createElement("div");
    top.className = "npc-top";
    var nm = document.createElement("span");
    nm.className = "npc-name";
    nm.textContent = name;
    top.appendChild(nm);
    if(type){
      var tp = document.createElement("span");
      tp.className = "npc-type " + (type==="攻略"?"t-love":"t-friend");
      tp.textContent = type==="攻略"?"♥ 攻略对象":"☆ 交友";
      top.appendChild(tp);
    }
    card.appendChild(top);

    /* 爱心 */
    var heartsDiv = document.createElement("div");
    heartsDiv.className = "hearts";
    var total = type==="攻略" ? maxHearts : 8;
    for(var h=0;h<total;h++){
      var ht = document.createElement("span");
      ht.className = "ht " + (h<heartNum?"on":"off");
      ht.textContent = "♥";
      heartsDiv.appendChild(ht);
    }
    card.appendChild(heartsDiv);

    /* 阶段 */
    if(stage){
      var sg = document.createElement("span");
      sg.className = "npc-stage";
      sg.textContent = stage;
      card.appendChild(sg);
    }

    container.appendChild(card);
  });
})();
</script>
</body>
</html>
