    <div class="chg-body">
      <div class="notice-board">
        <div class="sticky-list" id="stickyList"></div>
        <div class="board-deco">✦ ✦ ✦</div>
      </div>
    </div>
  </div>
</div>

<script>
(function(){
  var raw = `$1`;
  var lines = raw.split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var container = document.getElementById("stickyList");

  /* 关键字→图标映射 */
  var iconMap = {
    "金币":"💰","经验":"📖","好感":"💕","体力":"⚡",
    "耕种":"🌱","采矿":"⛏️","钓鱼":"🎣","采集":"🍂","战斗":"⚔️",
    "设施":"🏠","任务":"📌","技能":"⭐"
  };

  function getIcon(text){
    var keys = Object.keys(iconMap);
    for(var i=0;i<keys.length;i++){
      if(text.indexOf(keys[i])!==-1) return iconMap[keys[i]];
    }
    return "📝";
  }

  lines.forEach(function(line){
    /* 解析：名称 + 符号 + 数值 */
    var m = line.match(/^(.+?)([+\-])(\d+(?:\.\d+)?)$/);
    if(!m) return;
    var label = m[1].trim();
    var sign = m[2];
    var num = m[3];
    var isUp = (sign === "+");

    var el = document.createElement("div");
    el.className = "sticky " + (isUp ? "up" : "down");

    /* 图标 */
    var ico = document.createElement("div");
    ico.className = "sticky-ico";
    ico.textContent = getIcon(label);
    el.appendChild(ico);

    /* 文字 */
    var textDiv = document.createElement("div");
    textDiv.className = "sticky-text";

    var lb = document.createElement("span");
    lb.className = "sticky-label";
    lb.textContent = label;
    textDiv.appendChild(lb);

    var vl = document.createElement("span");
    vl.className = "sticky-val " + (isUp ? "v-up" : "v-down");
    vl.textContent = sign + num;
    textDiv.appendChild(vl);

    el.appendChild(textDiv);
    container.appendChild(el);
  });
})();
</script>
</body>
</html>
