<script>
(function(){
  var raw = `$1`;
  var lines = raw.split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var container = document.getElementById("invGrid");
  var capacity = 12;
  var items = [];

  /* 物品名→图标 */
  var iconMap = {
    "防风草":"🌿","土豆":"🥔","花椰菜":"🥦","大蒜":"🧄","芜菁":"🟣",
    "甘蓝":"🥬","南瓜":"🎃","甜瓜":"🍈","蓝莓":"🫐","草莓":"🍓",
    "玉米":"🌽","番茄":"🍅","小麦":"🌾","向日葵":"🌻","咖啡豆":"☕",
    "铁矿石":"🪨","铜矿石":"🟤","金矿石":"✨","煤炭":"⬛","石头":"🪨",
    "木材":"🪵","硬木":"🪓","纤维":"🧶","树液":"💧","树脂":"🍯",
    "基础肥料":"💩","高级肥料":"🧪","基础保水土壤":"💦","鱼饵":"🪱",
    "蛋":"🥚","牛奶":"🥛","羊毛":"🐑","蜂蜜":"🍯",
    "面包":"🍞","啤酒":"🍺","果酱":"🫙","腌菜":"🥒",
    "铜锭":"🟫","铁锭":"⬜","金锭":"🟡","铱锭":"💎",
    "钓竿":"🎣","剑":"⚔️","镐":"⛏️","斧":"🪓","锄":"🌱","水壶":"💧"
  };

  function getIcon(name){
    var base = name.replace(/★+/g,"").trim();
    var keys = Object.keys(iconMap);
    for(var i=0;i<keys.length;i++){
      if(base.indexOf(keys[i])!==-1) return iconMap[keys[i]];
    }
    return "📦";
  }

  function getStarCount(name){
    var m = name.match(/★+/);
    return m ? m[0].length : 0;
  }

  /* 解析 */
  lines.forEach(function(line){
    var cm = line.match(/^容量\s*=\s*(\d+)$/);
    if(cm){capacity = parseInt(cm[1]);return;}
    var im = line.match(/^(.+?)\s*[×x]\s*(\d+)$/i);
    if(im){
      items.push({name:im[1].trim(), qty:parseInt(im[2])});
    }
  });

  /* 容量条 */
  var pct = Math.min(items.length / capacity * 100, 100);
  document.getElementById("capFill").style.width = pct + "%";
  document.getElementById("capNum").textContent = items.length + " / " + capacity;

  /* 物品槽 */
  items.forEach(function(item){
    var stars = getStarCount(item.name);
    var baseName = item.name.replace(/★+/g,"").trim();
    var qClass = stars === 0 ? "" : stars === 1 ? "q1" : stars === 2 ? "q2" : "q3";

    var slot = document.createElement("div");
    slot.className = "slot" + (qClass ? " " + qClass : "");

    /* 星级角标 */
    if(stars > 0){
      var sd = document.createElement("div");
      sd.className = "slot-stars";
      var starColor = stars === 1 ? "star-s" : stars === 2 ? "star-g" : "star-i";
      for(var s=0;s<stars;s++) sd.innerHTML += '<span class="'+starColor+'">★</span>';
      slot.appendChild(sd);
    }

    /* 图标 */
    var ico = document.createElement("div");
    ico.className = "slot-ico";
    ico.textContent = getIcon(item.name);
    slot.appendChild(ico);

    /* 名称 */
    var nm = document.createElement("div");
    nm.className = "slot-name";
    nm.textContent = baseName;
    slot.appendChild(nm);

    /* 数量 */
    if(item.qty > 1){
      var qt = document.createElement("div");
      qt.className = "slot-qty";
      qt.textContent = "×" + item.qty;
      slot.appendChild(qt);
    }

    container.appendChild(slot);
  });

  /* 空槽补齐 */
  var empties = capacity - items.length;
  for(var e=0;e<empties;e++){
    var es = document.createElement("div");
    es.className = "slot empty";
    container.appendChild(es);
  }

})();
</script>
</body>
