  background:linear-gradient(180deg,#fff 0%,var(--gold-soft) 100%);
  border-color:var(--gold);color:var(--soil);
  box-shadow:2px 2px 0 rgba(0,0,0,.15);
  transform:translateY(-1px);
}
.chip:active{transform:translateY(0);box-shadow:1px 1px 0 rgba(0,0,0,.1);}
.chip.active{
  background:linear-gradient(180deg,var(--leaf-soft) 0%,var(--leaf) 100%);
  border-color:var(--leaf-dark);color:#fff;
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.15);
  text-shadow:1px 1px 0 rgba(0,0,0,.2);
}
.field[data-type="multi"] .chip.active{
  background:linear-gradient(180deg,var(--sky-soft) 0%,var(--sky-deep) 100%);
  border-color:#2a6aa0;
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.15);
}
.chip.active::after{
  content:"✓";position:absolute;top:-4px;right:-4px;
  width:14px;height:14px;font-size:9px;line-height:14px;text-align:center;
  background:var(--gold);color:var(--soil);
  border:1.5px solid var(--wood);
  border-radius:50%;
  box-shadow:1px 1px 0 rgba(0,0,0,.2);
  text-shadow:none;
}
.chip.dim{opacity:.3;}
.chip[data-locked="1"]{
  background:linear-gradient(180deg,var(--sunset) 0%,#c0392b 100%)!important;
  color:#fff!important;cursor:not-allowed;opacity:1!important;
  border-color:#8a2818!important;
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.2)!important;
  text-shadow:1px 1px 0 rgba(0,0,0,.2);
}
.chip[data-locked="1"]::after{
  content:"★";background:transparent;color:var(--gold);width:auto;height:auto;
  border:none;border-radius:0;padding:0 0 0 3px;font-size:10px;
  position:static;box-shadow:none;text-shadow:1px 1px 0 rgba(0,0,0,.3);
}

.custom-row{display:flex;align-items:center;gap:6px;min-width:0;}
.custom-prefix{
  font-size:11px;
  color:var(--wood);letter-spacing:.1em;flex-shrink:0;font-weight:700;
  white-space:nowrap;
  background:rgba(139,94,60,.1);
  padding:2px 6px;
  border:1px solid rgba(139,94,60,.2);
}
.custom-in{
  flex:1;min-width:0;width:100%;
  padding:6px 10px;font-size:12.5px;
  background:rgba(255,255,255,.7);
  border:2px solid rgba(139,94,60,.2);
  color:var(--soil);font-family:'ZCOOL KuaiLe','Noto Sans SC',sans-serif;outline:none;
  transition:all .2s ease;
  box-shadow:inset 1px 1px 0 rgba(0,0,0,.05);
}
.custom-in:focus{
  background:#fff;border-color:var(--leaf);
  box-shadow:inset 1px 1px 0 rgba(0,0,0,.05),0 0 0 2px rgba(74,140,63,.2);
}
.custom-in.has-val{
  border-color:var(--leaf-soft);
  background:rgba(255,255,255,.9);
}
.custom-in::placeholder{color:var(--soil-mute);font-size:11px;}
.custom-area{
  width:100%;max-width:100%;
  padding:8px 10px;font-size:12.5px;line-height:1.7;min-height:52px;
  background:rgba(255,255,255,.7);
  border:2px solid rgba(139,94,60,.2);
  color:var(--soil);font-family:'ZCOOL KuaiLe','Noto Sans SC',sans-serif;outline:none;resize:vertical;
  transition:all .2s ease;
  box-shadow:inset 1px 1px 0 rgba(0,0,0,.05);
}
.custom-area:focus{
  background:#fff;border-color:var(--leaf);
  box-shadow:inset 1px 1px 0 rgba(0,0,0,.05),0 0 0 2px rgba(74,140,63,.2);
}
.custom-area.has-val{
  border-color:var(--leaf-soft);background:rgba(255,255,255,.9);
}
.custom-area::placeholder{color:var(--soil-mute);font-size:11px;}

.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:10px 12px;}

.divider{
  font-weight:700;
  font-size:14px;text-align:center;color:var(--leaf);
  padding:8px 12px;margin:16px 0;letter-spacing:.25em;
  position:relative;word-break:break-word;text-indent:.25em;
}
.divider::before,.divider::after{
  content:"";position:absolute;top:50%;width:28px;height:3px;
  background:repeating-linear-gradient(90deg,var(--leaf-soft) 0px,var(--leaf-soft) 4px,transparent 4px,transparent 8px);
}
.divider::before{left:4px;}
.divider::after{right:4px;}
.divider .emoji{margin:0 4px;text-indent:0;}

/* 预览 */
.preview-box{
  background:linear-gradient(180deg,rgba(255,255,255,.75) 0%,rgba(245,237,212,.6) 100%);
  border:3px solid var(--wood);
  padding:14px 12px 12px;position:relative;margin-top:10px;
  box-shadow:inset 2px 2px 0 rgba(255,255,255,.3),inset -1px -1px 0 rgba(0,0,0,.08),3px 3px 0 rgba(0,0,0,.15);
  max-width:100%;
}
.preview-label{
  font-weight:700;
  font-size:11px;letter-spacing:.2em;color:var(--wood);
  display:inline-flex;align-items:center;gap:5px;margin-bottom:8px;
  max-width:60%;text-indent:.2em;
}
.preview-label::before{content:"📋";font-size:14px;flex-shrink:0;text-indent:0;}
.preview-stamp{
  position:absolute;top:10px;right:10px;
  background:linear-gradient(180deg,var(--leaf) 0%,var(--leaf-dark) 100%);
  color:#fff;
  padding:3px 10px;
  font-size:10px;font-weight:700;
  letter-spacing:.15em;
  border:2px solid var(--leaf-dark);
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.15);
  white-space:nowrap;transform:rotate(-2deg);text-indent:.15em;
}
.preview-content{
  font-size:13px;
  line-height:1.8;color:var(--soil);white-space:pre-wrap;
  font-family:'ZCOOL KuaiLe','Noto Sans SC',sans-serif;
  word-wrap:break-word;overflow-wrap:break-word;word-break:break-word;
  max-height:260px;
  overflow-y:auto;overflow-x:hidden;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;
  padding-right:8px;margin-top:6px;
  scrollbar-width:thin;
  scrollbar-color:rgba(139,94,60,.4) transparent;
}
.preview-content::-webkit-scrollbar{width:6px;}
.preview-content::-webkit-scrollbar-track{background:transparent;}
.preview-content::-webkit-scrollbar-thumb{
  background:linear-gradient(180deg,var(--wood) 0%,var(--wood-dark) 100%);
  border:1px solid rgba(0,0,0,.1);
}
.preview-content::-webkit-scrollbar-thumb:hover{background:var(--wood-dark);}
.preview-content b{color:var(--leaf-dark);font-weight:700;}
.preview-content i{color:var(--soil-mute);font-style:italic;}
.preview-content em{color:var(--sunset);font-style:normal;font-weight:700;}

.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px;}
.actions-row2{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-top:8px;}
.btn{
  padding:11px 6px;font-size:13px;font-weight:700;letter-spacing:.12em;
  cursor:pointer;border:2px solid transparent;
  transition:all .15s ease;
  font-family:'ZCOOL KuaiLe','Noto Sans SC',sans-serif;text-align:center;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  min-width:0;text-indent:.12em;
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.2);
}
.btn:active{transform:translateY(1px);box-shadow:inset 1px 1px 0 rgba(0,0,0,.1);}
.btn-send{
  background:linear-gradient(180deg,var(--leaf-soft) 0%,var(--leaf) 50%,var(--leaf-dark) 100%);
  border-color:var(--leaf-dark);color:#fff;
  text-shadow:1px 1px 0 rgba(0,0,0,.25);
}
.btn-send:hover{filter:brightness(1.1);}
.btn-copy{
  background:linear-gradient(180deg,var(--sky-soft) 0%,var(--sky) 50%,var(--sky-deep) 100%);
  border-color:#2a6aa0;color:#fff;
  text-shadow:1px 1px 0 rgba(0,0,0,.25);
}
.btn-copy:hover{filter:brightness(1.1);}
.btn-sub{
  background:linear-gradient(180deg,rgba(255,255,255,.9) 0%,rgba(245,237,212,.9) 100%);
  color:var(--soil);
  border-color:rgba(139,94,60,.3);
  font-size:11px;letter-spacing:.08em;font-weight:700;
  text-indent:.08em;
}
.btn-sub:hover{
  background:linear-gradient(180deg,var(--gold-soft) 0%,var(--gold) 100%);
  border-color:var(--wood);color:var(--soil);
}
.btn-clear{
  background:linear-gradient(180deg,rgba(255,255,255,.9) 0%,rgba(245,237,212,.9) 100%);
  color:var(--soil);
  border-color:rgba(139,94,60,.3);
  font-size:11px;letter-spacing:.08em;font-weight:700;
  text-indent:.08em;
}
.btn-clear:hover{
  background:linear-gradient(180deg,var(--berry-soft) 0%,var(--berry) 100%);
  color:#fff;border-color:#8a2818;
  text-shadow:1px 1px 0 rgba(0,0,0,.2);
}

.toast{
  position:fixed;left:50%;bottom:30px;transform:translateX(-50%) translateY(20px);
  background:linear-gradient(180deg,var(--leaf-soft) 0%,var(--leaf-dark) 100%);
  color:#fff;padding:8px 18px;font-size:13px;
  letter-spacing:.15em;opacity:0;pointer-events:none;transition:all .3s;
  border:2px solid var(--leaf-dark);
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),3px 3px 0 rgba(0,0,0,.2);
  z-index:9999;font-weight:700;
  max-width:90vw;white-space:nowrap;text-indent:.15em;
  text-shadow:1px 1px 0 rgba(0,0,0,.2);
}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0);}

.die{
  display:inline-flex;align-items:center;justify-content:center;
  width:22px;height:22px;border:2px solid var(--wood);
  font-size:12px;cursor:pointer;
  background:linear-gradient(180deg,var(--gold-soft),var(--gold));
  color:var(--soil);
  transition:all .25s ease;flex-shrink:0;
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.4),1px 1px 0 rgba(0,0,0,.15);
}
.die:hover{
  background:linear-gradient(180deg,var(--sunset),#c0392b);color:#fff;
  border-color:var(--wood-dark);
  transform:rotate(180deg);
  box-shadow:inset 1px 1px 0 rgba(255,255,255,.3),2px 2px 0 rgba(0,0,0,.2);
}

/* 季节色彩条 */
.season-bar{
  display:flex;height:6px;margin-bottom:4px;overflow:hidden;
  border:1px solid rgba(0,0,0,.1);
}
.season-bar div{flex:1;}
.season-bar .sp{background:#7dcea0;}
.season-bar .su{background:#f9e076;}
.season-bar .fa{background:#e67e22;}
.season-bar .wi{background:#5b9bd5;}

@media (max-width:420px){
  .paper{padding:16px 12px;}
  .pixel-stars{font-size:10px;}
  .title-main{font-size:clamp(22px,6.5vw,30px);}
  .title-sub{letter-spacing:.3em;font-size:11px;}
  .sec-title{font-size:13px;letter-spacing:.1em;}
  .sec-sub{font-size:10px;letter-spacing:.1em;}
  .sec-icon{font-size:18px;}
  .divider{font-size:12px;letter-spacing:.15em;}
  .divider::before,.divider::after{width:22px;}
  .field-label{font-size:12px;}
  .chip{font-size:11px;padding:4px 10px;}
  .custom-in,.custom-area{font-size:11.5px;padding:5px 8px;}
  .btn{font-size:12px;padding:10px 4px;}
  .btn-sub,.btn-clear{font-size:10px;}
  .preview-content{font-size:12px;}
  .preview-stamp{font-size:9px;padding:2px 8px;}
  .preview-label{font-size:10px;}
}

@media (max-width:360px){
  .paper{padding:14px 10px;}
  .grid-2{grid-template-columns:1fr;gap:10px;}
  .sec-icon{font-size:16px;}
  .sec-title{font-size:12px;letter-spacing:.08em;}
  .sec-sub{font-size:9px;}
  .field-label{font-size:11px;letter-spacing:.08em;}
  .field-label .hint{font-size:9px;}
  .chip{font-size:10px;padding:3px 8px;}
  .custom-prefix{font-size:10px;}
  .custom-in,.custom-area{font-size:11px;padding:5px 8px;}
  .btn{font-size:11px;padding:9px 3px;letter-spacing:.08em;}
  .btn-sub,.btn-clear{font-size:9.5px;letter-spacing:.04em;}
  .preview-content{font-size:11px;}
  .preview-stamp{font-size:8px;padding:2px 7px;letter-spacing:.12em;}
  .preview-label{font-size:9px;letter-spacing:.15em;}
  .divider{font-size:11px;}
  .die{width:20px;height:20px;font-size:11px;}
}

@media (min-width:520px){
  .paper{padding:24px 20px;}
  .sec-title{font-size:16px;letter-spacing:.18em;}
  .sec-sub{font-size:12px;letter-spacing:.18em;}
  .pixel-stars{font-size:12px;letter-spacing:.25em;}
  .title-sub{letter-spacing:.5em;font-size:14px;}
  .sec-icon{font-size:22px;}
  .field-label{font-size:14px;}
  .chip{font-size:13px;padding:5px 14px;}
  .custom-in,.custom-area{font-size:13px;padding:7px 12px;}
  .btn{font-size:14px;padding:12px 8px;}
  .btn-sub,.btn-clear{font-size:12px;}
  .preview-content{font-size:14px;}
}
</style>
</head>
<body>
<div class="paper" id="paper">
  <div class="corner-deco tl"></div>
  <div class="corner-deco tr"></div>
  <div class="corner-deco bl"></div>
  <div class="corner-deco br"></div>

  <div class="season-bar"><div class="sp"></div><div class="su"></div><div class="fa"></div><div class="wi"></div></div>

  <header class="masthead">
    <div class="pixel-stars">
      <span>星露谷物语 · 鹈鹕镇</span>
      <span class="star"></span>
      <span>新 农 夫 登 记 册</span>
    </div>
    <div class="title-main">新<span class="leaf">☘</span>农<span class="leaf">☘</span>夫<span class="leaf">☘</span>档<span class="leaf">☘</span>案</div>
    <div class="title-sub">鹈 鹕 镇 居 民 登 记 表</div>
    <div class="badge">🌱 爷爷的农场 · 新主人 🌱</div>
  </header>

  <!-- 壹 基本信息 -->
  <section class="section">
    <div class="sec-head"><span class="sec-icon">🏠</span><span class="sec-title">基 本 信 息</span><span class="sec-sub">— 你是谁？ —</span></div>
    <div class="sec-line"></div>

    <div class="field" data-type="custom-only" data-key="name">
      <div class="field-label">农场主姓名 <span class="hint">留空则随缘</span></div>
      <div class="custom-row"><span class="custom-prefix">姓名 ／</span><input class="custom-in" data-key="name" placeholder="写下你的名字 …"></div>
    </div>
    <div class="field" data-type="custom-only" data-key="farmname">
      <div class="field-label">农场名称 <span class="hint">留空则随缘</span></div>
      <div class="custom-row"><span class="custom-prefix">农场 ／</span><input class="custom-in" data-key="farmname" placeholder="给你的农场取个名 …"></div>
    </div>

    <div class="grid-2">
      <div class="field" data-type="single" data-key="gender">
        <div class="field-label">性别 <button class="die" data-random="gender">⚂</button></div>
        <div class="chips"></div>
        <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="gender" placeholder="自填覆盖 …"></div>
      </div>
      <div class="field" data-type="single" data-key="age">
        <div class="field-label">年龄 <button class="die" data-random="age">⚂</button></div>
        <div class="chips"></div>
        <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="age" placeholder="如28岁 …"></div>
      </div>
    </div>
  </section>

  <!-- 贰 外貌 -->
  <section class="section">
    <div class="sec-head"><span class="sec-icon">👤</span><span class="sec-title">外 貌 特 征</span><span class="sec-sub">— 像素形象 —</span></div>
    <div class="sec-line"></div>

    <div class="field" data-type="single" data-key="hair">
      <div class="field-label">发型发色 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="hair" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single" data-key="eye">
      <div class="field-label">眼睛 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="eye" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single" data-key="vibe">
      <div class="field-label">整体气质 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="vibe" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single" data-key="outfit">
      <div class="field-label">穿着打扮 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="outfit" placeholder="自填将覆盖选项 …"></div>
    </div>
  </section>

  <div class="divider"><span class="emoji">🌻</span>春 风 送 暖 · 新 的 开 始<span class="emoji">🌻</span></div>

  <!-- 叁 性格与技能 -->
  <section class="section">
    <div class="sec-head"><span class="sec-icon">💚</span><span class="sec-title">性 格 · 喜 好 · 技 能</span><span class="sec-sub">— 你的内心 —</span></div>
    <div class="sec-line"></div>

    <div class="field" data-type="multi" data-key="trait" data-max="3">
      <div class="field-label">性格特质 <span class="hint">多选最多三项 · 可追加</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">追加 ／</span><input class="custom-in" data-key="trait" placeholder="用、分隔多个 …"></div>
    </div>
    <div class="field" data-type="multi" data-key="hobby" data-max="3">
      <div class="field-label">兴趣爱好 <span class="hint">多选最多三项 · 可追加</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">追加 ／</span><input class="custom-in" data-key="hobby" placeholder="用、分隔多个 …"></div>
    </div>
    <div class="field" data-type="multi" data-key="skill" data-max="2">
      <div class="field-label">擅长领域 <span class="hint">多选最多两项 · 可追加</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">追加 ／</span><input class="custom-in" data-key="skill" placeholder="用、分隔多个 …"></div>
    </div>
    <div class="field" data-type="single" data-key="tone">
      <div class="field-label">说话方式 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="tone" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single-area" data-key="secret">
      <div class="field-label">不为人知的秘密 <span class="hint">自由填写 · 不限字数</span></div>
      <div class="chips"></div>
      <textarea class="custom-area" data-key="secret" placeholder="每个人都有不想说的事 … 比如：离开城市的真正原因、和某位镇民的旧缘 …"></textarea>
    </div>
  </section>

  <!-- 肆 来历 -->
  <section class="section">
    <div class="sec-head"><span class="sec-icon">📜</span><span class="sec-title">来 历 · 过 去</span><span class="sec-sub">— 城市往事 —</span></div>
    <div class="sec-line"></div>

    <div class="field" data-type="single" data-key="background">
      <div class="field-label">之前的生活 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="background" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single" data-key="reason">
      <div class="field-label">来到鹈鹕镇的原因 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="reason" placeholder="自填将覆盖选项 …"></div>
    </div>
    <div class="field" data-type="single-area" data-key="backstory">
      <div class="field-label">详细来历 <span class="hint">自由填写 · 不限字数</span></div>
      <div class="chips"></div>
      <textarea class="custom-area" data-key="backstory" placeholder="可以更详细地写写你的过去 … 比如在Joja公司的日子、和爷爷的回忆、逃离城市的契机 …"></textarea>
    </div>
  </section>

  <div class="divider"><span class="emoji">⭐</span>告 别 都 市 · 拥 抱 田 园<span class="emoji">⭐</span></div>

  <!-- 伍 游戏倾向 -->
  <section class="section">
    <div class="sec-head"><span class="sec-icon">🎯</span><span class="sec-title">游 戏 倾 向 · 目 标</span><span class="sec-sub">— 你的田园梦 —</span></div>
