      <div class="field-label">恋爱方式 <span class="hint">单选 · 可自填</span></div>
      <div class="chips"></div>
      <div class="custom-row"><span class="custom-prefix">自填 ／</span><input class="custom-in" data-key="approach" placeholder="自填覆盖 …"></div>
    </div>
    <div class="field" data-type="single-area" data-key="opening">
      <div class="field-label">初到农场的场景 <span class="hint">第一天的情景 · 不限字数</span></div>
      <div class="chips"></div>
      <textarea class="custom-area" data-key="opening" placeholder="自由描写你踏上农场的第一天 … 比如：提着行李箱走下巴士、第一次推开老旧的农舍门 …"></textarea>
    </div>
