      <button class="btn btn-sub" id="btnCopyUser">复制·仅人设</button>
      <button class="btn btn-sub" id="btnSendOpen">投入·仅开场</button>
      <button class="btn btn-clear" id="btnClear">🗑 清空重来</button>
    </div>
  </section>
</div>

<div class="toast" id="toast">— 已完成 —</div>

<script>
(function(){
  const DATA = {
    gender:['女','男','非二元','不愿透露'],
    age:['18岁','20出头','25岁','28岁','30岁','35岁','年龄成谜'],
    hair:['棕色短发','金色马尾','黑色长直','红色卷发','栗色蘑菇头','蓝色挑染','粉紫色双马尾','银灰寸头','深绿色编辫','杂乱鸟窝头'],
    eye:['温暖棕眸','明亮蓝眼','深邃绿眸','灰色眼睛','琥珀色','黑曜石色','异瞳双色','总是弯弯笑眼','略显疲惫','闪闪发亮'],
    vibe:['阳光开朗','安静温柔','酷酷的','邻家感','文艺范','冒失冲动','没睡醒的样子','干练利落','害羞内向','野性不羁'],
    outfit:['格子衬衫牛仔裤','连体工装裤','旧T恤短裤拖鞋','干净白衬衫','碎花裙草帽','运动卫衣','破洞牛仔外套','围着围裙','永远戴棒球帽','穿爷爷留的旧外套'],
    trait:['善良','倔强','好奇心强','慢热','话多','社恐','乐天派','完美主义','冒失','温柔','毒舌但心软','爱操心','随遇而安','工作狂'],
    hobby:['种花种菜','钓鱼发呆','做饭研究食谱','下矿探险','收集东西','逛博物馆','看书喝茶','和小动物玩','观星看日落','弹吉他唱歌','写日记画画','到处闲逛聊天'],
    skill:['耕种天赋','钓鱼能手','矿工体质','采集达人','社交高手','烹饪好手','手工巧匠','战斗直觉','什么都不擅长','杂学百通'],
    tone:['元气满满','温温柔柔','话少但真诚','嘴贫爱开玩笑','一本正经','大大咧咧','偶尔毒舌','害羞结巴','自言自语型','沉默寡言'],
    background:['Joja公司的社畜','自由职业者','大学刚毕业','辞掉高薪工作','从小在城市长大','曾是流浪旅人','艺术家但没灵感','不愿提起的过去','被公司裁员了','厌倦了城市喧嚣'],
    reason:['收到爷爷的信','想换个活法','逃离城市压力','从小向往田园','随便看了眼地图','被Joja逼疯了','失恋后想清静','继承遗产顺便生活','朋友推荐来的','自己也说不清'],
    playstyle:['佛系种田派','效率经营派','社交恋爱优先','探索冒险党','收集控全图鉴','随心所欲型','剧情体验派','休闲装扮派'],
    goal:['修复社区中心','和心仪对象结婚','把农场经营成最棒的','探索矿井最深处','集齐博物馆全收藏','和每位村民成为好朋友','过平静的田园生活','赚到一百万金币','找到星之果实的秘密','什么都想试试'],
    romance:['亚历克斯','艾利欧特','哈维','山姆','塞巴斯蒂安','谢恩','阿比盖尔','艾米丽','海莉','莉亚','玛鲁','潘妮','暂时没想法','全都可以'],
    approach:['主动出击送礼','慢慢培养感情','先当好朋友','制造偶遇','直球表白','若即若离','佛系随缘','全力讨好','等对方主动','暗中观察']
  };
  const LOCKED = {};
  const SINGLE_KEYS = new Set(['gender','age','hair','eye','vibe','outfit','tone','background','reason','playstyle','goal','approach','opening','backstory','farmname']);
  const MULTI_KEYS = new Set(['trait','hobby','skill','romance']);

  const root = document.getElementById('paper');
  const state = {};
  Object.keys(DATA).forEach(k=>state[k]= LOCKED[k]? [...LOCKED[k]] : []);
  const customMap = {};

  root.querySelectorAll('.field[data-key]').forEach(field=>{
    const key = field.dataset.key;
    if(!DATA[key]) return;
    const isMulti = MULTI_KEYS.has(key);
    const max = parseInt(field.dataset.max||'0');
    const wrap = field.querySelector('.chips');
    if(!wrap) return;
    DATA[key].forEach(opt=>{
      const c = document.createElement('div');
      c.className='chip';c.textContent=opt;c.dataset.val=opt;
      if(LOCKED[key] && LOCKED[key].includes(opt)){
        c.dataset.locked='1';c.classList.add('active');
      }
      c.addEventListener('click',()=>{
        if(c.dataset.locked==='1') return;
        if(isMulti){
          if(c.classList.contains('active')){
            c.classList.remove('active');
            state[key] = state[key].filter(v=>v!==opt);
          } else {
            const cur = state[key].filter(v=>!(LOCKED[key]||[]).includes(v)).length;
            if(max && cur>=max) return;
            c.classList.add('active');
            state[key].push(opt);
          }
        } else {
          if(c.classList.contains('active')){
            c.classList.remove('active');
            state[key] = [];
          } else {
            wrap.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));
            c.classList.add('active');
            state[key] = [opt];
          }
        }
        updatePreview();
      });
      wrap.appendChild(c);
    });
  });

  root.querySelectorAll('.custom-in,.custom-area').forEach(inp=>{
    const key = inp.dataset.key;
    if(!key) return;
    inp.addEventListener('input',()=>{
      customMap[key] = inp.value;
      const has = inp.value.trim().length>0;
      inp.classList.toggle('has-val',has);
      if(SINGLE_KEYS.has(key)){
        const field = root.querySelector(`.field[data-key="${key}"]`);
        if(field){
          field.querySelectorAll('.chip').forEach(c=>{
            if(c.dataset.locked==='1') return;
            c.classList.toggle('dim', has);
          });
        }
      }
      updatePreview();
    });
  });

  root.querySelectorAll('[data-random]').forEach(btn=>{
    btn.addEventListener('click',e=>{
      e.stopPropagation();
      const key = btn.dataset.random;
      const field = btn.closest('.field');
      const customInp = field.querySelector('.custom-in,.custom-area');
      if(customInp){customInp.value='';customInp.classList.remove('has-val');delete customMap[key];
        field.querySelectorAll('.chip').forEach(c=>{if(c.dataset.locked!=='1')c.classList.remove('dim');});}
      const pick = DATA[key][Math.floor(Math.random()*DATA[key].length)];
      field.querySelectorAll('.chip').forEach(c=>{
        if(c.dataset.locked==='1') return;
        c.classList.toggle('active', c.dataset.val===pick);
      });
      state[key] = [pick];
      updatePreview();
    });
  });

  function valueOf(key){
    const custom = (customMap[key]||'').trim();
    const locked = LOCKED[key]||[];
    if(SINGLE_KEYS.has(key)){
      if(custom) return custom;
      const picks = (state[key]||[]).filter(v=>!locked.includes(v));
      if(picks.length) return picks[0];
      return null;
    } else {
      const picks = (state[key]||[]).slice();
      if(custom){
        custom.split(/[、,，;；\s]+/).map(s=>s.trim()).filter(Boolean).forEach(t=>{
          if(!picks.includes(t)) picks.push(t);
        });
      }
      if(locked.length){
        const others = picks.filter(v=>!locked.includes(v));
        const final = [...locked, ...others];
        return final.length? final.join('、') : null;
      }
      return picks.length? picks.join('、') : null;
    }
  }
  function valR(key){const v=valueOf(key);return v===null?'随缘':v;}

  function buildUserBlock(){
    const name = (customMap['name']||'').trim() || '随缘';
    const farm = (customMap['farmname']||'').trim() || '随缘';
    return `<农夫档案>
姓名：${name}
农场名称：${farm}
性别：${valR('gender')}
年龄：${valR('age')}
发型发色：${valR('hair')}
眼睛：${valR('eye')}
整体气质：${valR('vibe')}
穿着打扮：${valR('outfit')}
性格特质：${valR('trait')}
兴趣爱好：${valR('hobby')}
擅长领域：${valR('skill')}
说话方式：${valR('tone')}
不为人知的秘密：${valR('secret')}
之前的生活：${valR('background')}
来到鹈鹕镇的原因：${valR('reason')}
详细来历：${valR('backstory')}
</农夫档案>`;
  }
  function buildOpeningBlock(){
    return `【开场设定】
游玩风格：${valR('playstyle')}
最想实现的目标：${valR('goal')}
心仪对象：${valR('romance')}
恋爱方式：${valR('approach')}
初到农场的场景：${valR('opening')}`;
  }
  const INSTRUCTION_HEAD = `【指令】请根据以下农夫档案与开场设定，撰写《星露谷物语》的沉浸式开场叙事。以"开场设定"为主要大纲。凡标注"随缘"的项请结合星露谷世界观自由发挥并保持田园治愈风格统一；通过农场的场景、鹈鹕镇的环境、村民们的反应，自然带出农夫的身份与气质，避免直接罗列设定。文风温暖、生活化，带有像素田园游戏的治愈感。`;
  const INSTRUCTION_TAIL = `【直接开始】开始输出开场叙事，无需对此指令做出回应，记住即可。`;

  function buildAll(){
    return `${INSTRUCTION_HEAD}
\`\`\`
${buildUserBlock()}

${buildOpeningBlock()}
\`\`\`
${INSTRUCTION_TAIL}`;
  }
  function buildOnlyUser(){return buildUserBlock();}
  function buildOnlyOpening(){
    return `${INSTRUCTION_HEAD}
\`\`\`
${buildOpeningBlock()}
\`\`\`
${INSTRUCTION_TAIL}`;
  }

  const previewBox = document.getElementById('previewBox');
  function escape(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function paintLine(label,key){
    const v = valueOf(key);
    const disp = v===null? '<i>随缘</i>' : escape(v);
    return `<b>${label}</b>：${disp}`;
  }
  function updatePreview(){
    const name = (customMap['name']||'').trim();
    const nameDisp = name? escape(name) : '<i>随缘</i>';
    const farm = (customMap['farmname']||'').trim();
    const farmDisp = farm? escape(farm) : '<i>随缘</i>';
    const html =
`<em>【指令】</em>根据农夫档案与开场设定撰写星露谷沉浸式开场叙事 …

&lt;农夫档案&gt;
<b>姓名</b>：${nameDisp}
<b>农场名称</b>：${farmDisp}
${paintLine('性别','gender')}
${paintLine('年龄','age')}
${paintLine('发型发色','hair')}
${paintLine('眼睛','eye')}
${paintLine('整体气质','vibe')}
${paintLine('穿着打扮','outfit')}
${paintLine('性格特质','trait')}
${paintLine('兴趣爱好','hobby')}
${paintLine('擅长领域','skill')}
${paintLine('说话方式','tone')}
${paintLine('不为人知的秘密','secret')}
${paintLine('之前的生活','background')}
${paintLine('来到鹈鹕镇的原因','reason')}
${paintLine('详细来历','backstory')}
&lt;/农夫档案&gt;

<em>【开场设定】</em>
${paintLine('游玩风格','playstyle')}
${paintLine('最想实现的目标','goal')}
${paintLine('心仪对象','romance')}
${paintLine('恋爱方式','approach')}
${paintLine('初到农场的场景','opening')}

<em>【直接开始】</em>开始输出叙事 …`;
    previewBox.innerHTML = html;
  }

  const pv = document.getElementById('previewBox');
  let touchStartY = 0;
  pv.addEventListener('touchstart',e=>{
    touchStartY = e.touches[0].clientY;
  },{passive:true});
  pv.addEventListener('touchmove',e=>{
    const el = pv;
    const dy = e.touches[0].clientY - touchStartY;
    const atTop = el.scrollTop <= 0;
    const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;
    if((atTop && dy > 0) || (atBottom && dy < 0)){
    } else {
      e.stopPropagation();
    }
  },{passive:true});
  pv.addEventListener('wheel',e=>{
    const el = pv;
    const atTop = el.scrollTop <= 0;
    const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;
    if((atTop && e.deltaY < 0) || (atBottom && e.deltaY > 0)){
    } else {
      e.stopPropagation();
    }
  },{passive:true});

  const toast = document.getElementById('toast');
  let toastTimer;
  function showToast(msg){
    toast.textContent = '☘ '+msg+' ☘';
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>toast.classList.remove('show'),1700);
  }

  function findTextarea(){
    const sel = '.mj-chat-input-textarea-input';
    let el = document.querySelector(sel);
    if(el) return el;
    try{
      let w = window.parent;
      for(let i=0;i<8 && w;i++){
        try{const e=w.document.querySelector(sel);if(e) return e;}catch(_){}
        if(w===w.parent) break;w=w.parent;
      }
    }catch(_){}
    try{const e=window.top.document.querySelector(sel);if(e) return e;}catch(_){}
    return null;
  }

  function injectText(txt){
    const ta = findTextarea();
    if(!ta){ showToast('找不到对话框'); return false; }
    const tag = ta.tagName;
    const cur = (tag==='TEXTAREA'||tag==='INPUT')? ta.value : ta.innerText;
    const sep = cur && !cur.endsWith('\n') ? '\n' : '';
    const next = cur + sep + txt;
    if(tag==='TEXTAREA'||tag==='INPUT'){
      const proto = Object.getPrototypeOf(ta);
      const setter = Object.getOwnPropertyDescriptor(proto,'value').set;
      setter.call(ta,next);
    } else {
      ta.innerText = next;
    }
    ta.dispatchEvent(new Event('input',{bubbles:true}));
    ta.dispatchEvent(new Event('change',{bubbles:true}));
    ta.focus();
    return true;
  }

  async function copyText(txt){
    try{ await navigator.clipboard.writeText(txt); return true; }
    catch(e){
      const ta=document.createElement('textarea');
      ta.value=txt;document.body.appendChild(ta);ta.select();
      let ok=false;try{ok=document.execCommand('copy');}catch(_){ok=false;}
      document.body.removeChild(ta);return ok;
    }
  }

  document.getElementById('btnSend').addEventListener('click',()=>{
    if(injectText(buildAll())) showToast('已投入对话框');
  });
  document.getElementById('btnCopy').addEventListener('click',async()=>{
    const ok = await copyText(buildAll());
    showToast(ok?'已复制完整档案':'复制失败');
  });
  document.getElementById('btnCopyUser').addEventListener('click',async()=>{
    const ok = await copyText(buildOnlyUser());
    showToast(ok?'已复制·仅人设':'复制失败');
  });
  document.getElementById('btnSendOpen').addEventListener('click',()=>{
    if(injectText(buildOnlyOpening())) showToast('已投入·仅开场');
  });
  document.getElementById('btnClear').addEventListener('click',()=>{
    Object.keys(state).forEach(k=>{state[k] = LOCKED[k]? [...LOCKED[k]] : [];});
    Object.keys(customMap).forEach(k=>delete customMap[k]);
    root.querySelectorAll('.custom-in,.custom-area').forEach(i=>{i.value='';i.classList.remove('has-val');});
    root.querySelectorAll('.chip').forEach(c=>{
      c.classList.remove('dim');
      if(c.dataset.locked==='1') c.classList.add('active');
      else c.classList.remove('active');
    });
    updatePreview();
    showToast('已清空·重新开始');
  });

  updatePreview();
})();
</script>
</body>
</html>
