    cursor:pointer;user-select:none;text-align:center;
    font-size:15px;letter-spacing:1px;color:#fff6e2;
    padding:14px 16px;border-radius:12px;
    background:linear-gradient(180deg,var(--plank) 0%,var(--plank-d) 100%);
