    box-shadow:0 3px 0 var(--wood-d),0 0 0 3px rgba(0,0,0,.12);
    text-shadow:1px 1px 0 rgba(0,0,0,.35);
    transition:background .35s ease,border-radius .35s ease,box-shadow .35s ease,padding .35s ease;
  }
  .stg-title .arrow{transition:transform .35s ease;font-size:12px;}
  .stg.open .stg-title{
    background:linear-gradient(180deg,var(--wood) 0%,var(--wood-d) 100%);
    border-radius:12px 12px 0 0;padding:15px 16px;
    box-shadow:0 3px 0 var(--wood-d),inset 0 2px 0 rgba(255,255,255,.14);
  }
  .stg.open .stg-title .arrow{transform:rotate(180deg);}

  /* ===== 折叠 ===== */
  .stg-wrap{display:grid;grid-template-rows:0fr;transition:grid-template-rows .38s ease;}
  .stg.open .stg-wrap{grid-template-rows:1fr;}
  .stg-body{overflow:hidden;min-height:0;padding:0 2px;}
  .stg.open .stg-body{padding:12px 2px 4px;}

  /* ===== 木箱外框 ===== */
  .crate{
    position:relative;
    background:linear-gradient(180deg,#7a5630 0%,#5e3f1e 50%,#4a3018 100%);
    border:5px solid var(--plank-d);border-radius:10px;
    padding:14px 10px 12px;
    box-shadow:inset 0 3px 0 rgba(255,255,255,.08),inset 0 -4px 10px rgba(0,0,0,.35),0 4px 0 rgba(0,0,0,.3);
  }
  /* 木纹 */
  .crate::before{
    content:"";position:absolute;inset:0;border-radius:7px;pointer-events:none;
    background:
      repeating-linear-gradient(180deg,transparent 0 12px,rgba(0,0,0,.06) 12px 13px),
      repeating-linear-gradient(90deg,transparent 0 40px,rgba(255,255,255,.03) 40px 41px);
  }
  /* 铁扣装饰 - 左 */
  .crate-latch-l,.crate-latch-r{
    position:absolute;top:50%;width:14px;height:26px;
    background:linear-gradient(180deg,var(--iron),var(--iron-d));
    border-radius:3px;border:2px solid #444;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.3),0 2px 3px rgba(0,0,0,.4);
    z-index:2;
  }
  .crate-latch-l{left:-8px;transform:translateY(-50%);}
  .crate-latch-r{right:-8px;transform:translateY(-50%);}
  /* 铁钉 */
  .crate-latch-l::after,.crate-latch-r::after{
    content:"";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
    width:6px;height:6px;border-radius:50%;
    background:radial-gradient(circle at 35% 30%,#ccc,#777);
    border:1px solid #555;
  }

  /* ===== 物品总数信息条 ===== */
  .crate-info{
    display:flex;align-items:center;justify-content:center;gap:8px;
    margin:0 0 12px;padding:6px 10px;
    background:rgba(0,0,0,.3);border-radius:6px;
  }
  .crate-info span{font-size:11px;color:#dcc89a;text-shadow:1px 1px 0 rgba(0,0,0,.5);}
  .crate-info b{color:var(--gold);}

  /* ===== 分组架子 ===== */
  .shelf{margin:0 0 10px;position:relative;z-index:1;}
  .shelf:last-child{margin-bottom:0;}

  /* 架子标签 */
  .shelf-tag{
    display:inline-block;font-size:10px;color:#c4955e;
    background:rgba(0,0,0,.35);padding:4px 10px;border-radius:4px 4px 0 0;
    margin:0 0 -2px 8px;text-shadow:1px 1px 0 rgba(0,0,0,.5);
    position:relative;z-index:1;
  }

  /* 架子板（横向滚动） */
  .shelf-board{
    display:flex;gap:8px;overflow-x:auto;overflow-y:hidden;
    padding:10px 8px 12px;
    background:linear-gradient(180deg,var(--plank) 0%,var(--plank-d) 100%);
    border:3px solid var(--plank-d);border-radius:6px;
    box-shadow:inset 0 2px 0 rgba(255,255,255,.1),inset 0 -3px 6px rgba(0,0,0,.25),0 3px 0 var(--wood-d);
    -webkit-overflow-scrolling:touch;
    scrollbar-width:thin;scrollbar-color:var(--wood-d) transparent;
  }
  .shelf-board::-webkit-scrollbar{height:6px;}
  .shelf-board::-webkit-scrollbar-track{background:transparent;}
  .shelf-board::-webkit-scrollbar-thumb{background:var(--wood-d);border-radius:3px;}

  /* 架子底部木板支撑线 */
  .shelf-board::after{
    content:"";position:absolute;bottom:0;left:8px;right:8px;height:3px;
    background:var(--plank-d);border-radius:2px;
  }

  /* ===== 物品块 ===== */
  .item{
    flex:0 0 auto;width:78px;
    background:var(--slot-bg);border:2px solid var(--slot-border);border-radius:7px;
    display:flex;flex-direction:column;align-items:center;justify-content:center;
    padding:8px 4px 6px;position:relative;
    box-shadow:inset 0 2px 4px rgba(0,0,0,.4),0 1px 0 rgba(255,255,255,.05);
    transition:transform .15s ease;
  }
  .item:hover{transform:translateY(-3px) scale(1.04);}

  /* 品质光晕 */
  .item.q1{box-shadow:inset 0 0 10px rgba(192,192,192,.2),inset 0 2px 4px rgba(0,0,0,.4);}
  .item.q2{box-shadow:inset 0 0 10px rgba(244,185,66,.25),inset 0 2px 4px rgba(0,0,0,.4);}
  .item.q3{box-shadow:inset 0 0 10px rgba(180,136,214,.25),inset 0 2px 4px rgba(0,0,0,.4);}

  .item-ico{font-size:22px;margin-bottom:3px;filter:drop-shadow(1px 1px 0 rgba(0,0,0,.5));}
  .item-name{
    font-size:8px;color:#dcc89a;text-align:center;line-height:1.3;
    max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
    text-shadow:1px 1px 0 rgba(0,0,0,.5);
  }
  .item-qty{
    position:absolute;bottom:3px;right:4px;
    font-size:10px;color:#fff;
    background:rgba(0,0,0,.55);padding:2px 5px;border-radius:4px;
    text-shadow:1px 1px 0 rgba(0,0,0,.5);
  }
  .item-stars{
    position:absolute;top:3px;right:3px;
    font-size:8px;line-height:1;
    filter:drop-shadow(0 1px 1px rgba(0,0,0,.5));
  }
  .star-s{color:#c0c0c0;}
  .star-g{color:var(--gold);}
  .star-i{color:#b488d6;}
</style>
</head>
<body>
<div class="stg" id="stgBar">
  <div class="stg-title" onclick="this.parentElement.classList.toggle('open')">
    <span>📦 储物箱</span><span class="arrow">▼</span>
  </div>
  <div class="stg-wrap">
    <div class="stg-body">
      <div class="crate">
        <div class="crate-latch-l"></div>
        <div class="crate-latch-r"></div>
        <div class="crate-info" id="crateInfo"></div>
        <div id="shelfContainer"></div>
      </div>
    </div>
  </div>
</div>

<script>
(function(){
  var raw = `$1`;
  var lines = raw.split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  var container = document.getElementById("shelfContainer");
  var infoEl = document.getElementById("crateInfo");

  var iconMap = {
    "防风草":"🌿","土豆":"🥔","花椰菜":"🥦","大蒜":"🧄","芜菁":"🟣",
    "甘蓝":"🥬","南瓜":"🎃","甜瓜":"🍈","蓝莓":"🫐","草莓":"🍓",
    "玉米":"🌽","番茄":"🍅","小麦":"🌾","向日葵":"🌻","咖啡豆":"☕",
    "铜矿石":"🟤","铁矿石":"🪨","金矿石":"✨","铱矿石":"💜","煤炭":"⬛","石头":"🪨",
    "木材":"🪵","硬木":"🪓","纤维":"🧶","干草":"🌾",
    "史莱姆黏液":"🟢","蝙蝠翅膀":"🦇","太阳精华":"☀️","虫肉":"🐛",
    "鲈鱼":"🐟","鲤鱼":"🐟","鲶鱼":"🐟","虹鳟鱼":"🌈","大嘴鲈鱼":"🐟",
    "蛋":"🥚","牛奶":"🥛","羊毛":"🐑","蜂蜜":"🍯","松露":"🍄",
    "宝石":"💎","钻石":"💎","紫水晶":"🔮","红宝石":"❤️","翡翠":"💚"
  };

  /* 分类关键字 */
  var categories = [
    {name:"矿石·材料", keys:["矿石","煤炭","石头","木材","硬木","纤维","干草"]},
    {name:"作物·农产", keys:["防风草","土豆","花椰菜","大蒜","芜菁","甘蓝","南瓜","甜瓜","蓝莓","草莓","玉米","番茄","小麦","向日葵","咖啡","蛋","牛奶","羊毛","蜂蜜","松露"]},
    {name:"鱼获", keys:["鱼","虹鳟"]},
    {name:"战利品", keys:["史莱姆","蝙蝠","精华","虫肉","牙","翅膀"]},
    {name:"宝石·杂项", keys:["宝石","钻石","水晶","红宝石","翡翠"]}
  ];

  function getIcon(name){
    var base = name.replace(/★+/g,"").trim();
    var keys = Object.keys(iconMap);
    for(var i=0;i<keys.length;i++){
      if(base.indexOf(keys[i])!==-1) return iconMap[keys[i]];
    }
    return "📦";
  }

  function getStarCount(name){var m=name.match(/★+/);return m?m[0].length:0;}

  function categorize(name){
    var base = name.replace(/★+/g,"").trim();
    for(var c=0;c<categories.length;c++){
      for(var k=0;k<categories[c].keys.length;k++){
        if(base.indexOf(categories[c].keys[k])!==-1) return categories[c].name;
      }
    }
    return "其他";
  }

  /* 解析 */
  var items = [];
  var totalQty = 0;
  lines.forEach(function(line){
    var m = line.match(/^(.+?)\s*[×x]\s*(\d+)$/i);
    if(m){
      var qty = parseInt(m[2]);
      items.push({name:m[1].trim(), qty:qty, cat:categorize(m[1])});
      totalQty += qty;
    }
  });

  /* 信息条 */
  infoEl.innerHTML = '<span>物品种类 <b>'+items.length+'</b></span><span>·</span><span>总数量 <b>'+totalQty+'</b></span>';

  /* 按类分组 */
  var grouped = {};
  items.forEach(function(it){
    if(!grouped[it.cat]) grouped[it.cat]=[];
    grouped[it.cat].push(it);
  });

  /* 渲染架子 */
  var catOrder = categories.map(function(c){return c.name;}).concat(["其他"]);
  catOrder.forEach(function(catName){
    if(!grouped[catName]) return;
    var shelf = document.createElement("div");
    shelf.className = "shelf";

    var tag = document.createElement("div");
    tag.className = "shelf-tag";
    tag.textContent = catName;
    shelf.appendChild(tag);

    var board = document.createElement("div");
    board.className = "shelf-board";

    grouped[catName].forEach(function(it){
      var stars = getStarCount(it.name);
      var baseName = it.name.replace(/★+/g,"").trim();
      var qClass = stars===0?"":stars===1?"q1":stars===2?"q2":"q3";

      var el = document.createElement("div");
      el.className = "item"+(qClass?" "+qClass:"");

      if(stars>0){
        var sd = document.createElement("div");
        sd.className = "item-stars";
        var sc = stars===1?"star-s":stars===2?"star-g":"star-i";
        for(var s=0;s<stars;s++) sd.innerHTML += '<span class="'+sc+'">★</span>';
        el.appendChild(sd);
      }

      var ico = document.createElement("div");
      ico.className = "item-ico";
      ico.textContent = getIcon(it.name);
      el.appendChild(ico);

      var nm = document.createElement("div");
      nm.className = "item-name";
      nm.textContent = baseName;
      el.appendChild(nm);

      if(it.qty > 1){
        var qt = document.createElement("div");
        qt.className = "item-qty";
        qt.textContent = "×"+it.qty;
        el.appendChild(qt);
      }

      board.appendChild(el);
    });

    shelf.appendChild(board);
    container.appendChild(shelf);
  });
})();
</script>
</body>
</html>
